+
+      .checkbox-label {
+        display: inline-flex;
+        flex-wrap: wrap;
+        gap: 0.25rem;
+        font-weight: 600;
+        line-height: 1.45;
+        cursor: pointer;
+      }
+
+      .required-mark {
+        color: var(--accent);
+      }
+
+      .help-text,
+      .error-text,
+      .status-text {
+        margin: 0;
