+        status.textContent = "";
+
+        if (!checkbox.checked) {
+          setErrorState(true);
+          checkbox.focus();
+          return;
+        }
+
+        setErrorState(false);
+        status.textContent = "Thanks — your consent has been recorded.";
+        status.hidden = false;
+        form.reset();
+      });
+
+      checkbox.addEventListener("change", () => {
+        if (checkbox.checked) {
+          setErrorState(false);
+        }
+      });
+
+      setErrorState(false);
+    </script>
+  </body>
+</html>
*** End Patch
