 <!doctype html>
 <html lang="en">
   <head>
     <meta charset="utf-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1" />
     <title>Terms Consent</title>
     <style>
       :root {
         color-scheme: dark;
         --bg: #0b1020;
         --panel: #11192d;
         --panel-border: #25314d;
         --text: #f3f7ff;
         --muted: #a9b7d1;
         --accent: #7c9dff;
         --accent-strong: #9eb6ff;
         --focus: #ffd166;
         --error: #ff7c8a;
         --shadow: 0 24px 70px rgba(0, 0, 0, 0.42);
       }

       * {
         box-sizing: border-box;
       }

       html,
       body {
         min-height: 100%;
       }

       body {
         margin: 0;
         font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
         background:
           radial-gradient(circle at top, rgba(124, 157, 255, 0.22), transparent 30%),
           linear-gradient(180deg, #0b1020 0%, #090d18 100%);
         color: var(--text);
       }

       a {
         color: var(--accent-strong);
       }

       .skip-link {
         position: absolute;
         left: 1rem;
         top: 1rem;
         transform: translateY(-180%);
         padding: 0.75rem 1rem;
         border-radius: 0.75rem;
         background: var(--text);
         color: #08101f;
         text-decoration: none;
         z-index: 10;
       }

       .skip-link:focus {
         transform: translateY(0);
       }

       main {
         min-height: 100vh;
         display: grid;
         place-items: center;
         padding: 2rem 1rem;
       }

       .card {
         width: min(100%, 34rem);
         padding: 2rem;
         border: 1px solid var(--panel-border);
         border-radius: 1.5rem;
         background: rgba(17, 25, 45, 0.92);
         box-shadow: var(--shadow);
         backdrop-filter: blur(14px);
       }

       .eyebrow {
         margin: 0 0 0.5rem;
         color: var(--accent);
         font-size: 0.9rem;
         font-weight: 600;
         letter-spacing: 0.04em;
         text-transform: uppercase;
       }

       h1 {
         margin: 0;
         font-size: clamp(1.75rem, 4vw, 2.4rem);
         line-height: 1.1;
       }

       .lead {
         margin: 0.75rem 0 0;
         color: var(--muted);
         line-height: 1.6;
       }

       form {
         margin-top: 1.75rem;
       }

       .form-field {
         display: grid;
         gap: 0.75rem;
         padding: 1rem;
         border: 1px solid rgba(158, 182, 255, 0.18);
         border-radius: 1rem;
         background: rgba(255, 255, 255, 0.03);
       }

       .checkbox-row {
         display: flex;
         gap: 0.85rem;
         align-items: flex-start;
       }

       .checkbox-row input {
         width: 1.15rem;
         height: 1.15rem;
         margin: 0.2rem 0 0;
         accent-color: var(--accent);
         flex: none;
       }

       .checkbox-label {
         display: inline-flex;
         flex-wrap: wrap;
         gap: 0.25rem;
         font-weight: 600;
         line-height: 1.45;
         cursor: pointer;
       }

       .required-mark {
         color: var(--accent);
       }

       .help-text,
       .error-text,
       .status-text {
         margin: 0;
         font-size: 0.95rem;
         line-height: 1.5;
       }

       .help-text {
         color: var(--muted);
       }

       .error-text {
         color: var(--error);
       }

       .status-text {
         margin-top: 1rem;
         color: var(--accent-strong);
       }

       .actions {
         display: flex;
         justify-content: flex-end;
         margin-top: 1.25rem;
       }

       button {
         border: 0;
         border-radius: 999px;
         padding: 0.9rem 1.35rem;
         background: linear-gradient(135deg, var(--accent), #5a7ef7);
         color: #08101f;
         font: inherit;
         font-weight: 700;
         cursor: pointer;
         box-shadow: 0 10px 24px rgba(90, 126, 247, 0.28);
       }

       button:hover {
         filter: brightness(1.05);
       }

       button:focus-visible,
       input:focus-visible,
       a:focus-visible {
         outline: 3px solid var(--focus);
         outline-offset: 3px;
       }

       @media (max-width: 28rem) {
         .card {
           padding: 1.25rem;
           border-radius: 1.25rem;
         }

         .actions {
           justify-content: stretch;
         }

         button {
           width: 100%;
         }
       }

       @media (forced-colors: active) {
         .card,
         .form-field {
           border-color: CanvasText;
         }

         .skip-link {
           border: 1px solid CanvasText;
         }

         button {
           border: 1px solid ButtonText;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <main id="main-content"></main>

     <script>
       const app = document.getElementById("main-content");

       function ConsentField() {
         return `
           <div class="form-field">
             <div class="checkbox-row">
               <input id="agree-terms" name="agreeTerms" type="checkbox" required aria-describedby="agree-help agree-error" />
               <div>
                 <label class="checkbox-label" for="agree-terms">
                   I agree to the terms of use <span class="required-mark" aria-hidden="true">*</span>
                 </label>
                 <p class="help-text" id="agree-help">Required to continue.</p>
                 <p class="error-text" id="agree-error" hidden>Error: You must agree to the terms of use.</p>
               </div>
             </div>
           </div>
         `;
       }

       function App() {
         return `
           <section class="card" aria-labelledby="consent-title">
             <p class="eyebrow">Consent</p>
             <h1 id="consent-title">Agree to continue</h1>
             <p class="lead">Please confirm that you accept the terms before moving forward.</p>

             <form id="consent-form" novalidate>
               ${ConsentField()}

               <div class="actions">
                 <button type="submit">Continue</button>
               </div>

               <p class="status-text" id="form-status" aria-live="polite" hidden></p>
             </form>
           </section>
         `;
       }

       app.innerHTML = App();

       const form = document.getElementById("consent-form");
       const checkbox = document.getElementById("agree-terms");
       const error = document.getElementById("agree-error");
       const status = document.getElementById("form-status");

       function setErrorState(isInvalid) {
         checkbox.setAttribute("aria-invalid", isInvalid ? "true" : "false");
         error.hidden = !isInvalid;
       }

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         status.hidden = true;
         status.textContent = "";

         if (!checkbox.checked) {
           setErrorState(true);
           checkbox.focus();
           return;
         }

         setErrorState(false);
         status.textContent = "Thanks — your consent has been recorded.";
         status.hidden = false;
         form.reset();
       });

       checkbox.addEventListener("change", () => {
         if (checkbox.checked) {
           setErrorState(false);
         }
       });

       setErrorState(false);
     </script>
   </body>
 </html>

